#pragma once
/*
 * map_geometry/  -  abstract cartographic context: a small synthetic TIN.
 *
 * Static data (terrain_data.h, generated by tools/gen_terrain.py) is a fixed set of
 * 3D vertices, a triangulation, edges, lit facets and a ridge line. From it this module
 * derives, ONCE at init, the sea-level coastline by contouring the TIN (marching
 * triangles, integer math). That coastline is therefore consistent with the surface
 * underneath it, not a separate drawing.
 *
 * Everything is stored in world space (north up, quarter-pixel units). Projecting it to
 * the instrument for a given dial rotation is done once per dial index and cached: while
 * the wrist is still, or only the time changes, no geometry is recomputed.
 *
 * Points are pixel offsets from the instrument centre (x right, y down).
 */
#include <stdint.h>
#include <stdbool.h>
#include "terrain_data.h"

#define MG_MAX_SEGS 32

typedef struct {
  int16_t x, y;
} MgPt;

typedef struct {
  MgPt a, b;
} MgSeg;

typedef struct {
  bool     valid;
  uint16_t key;            /* dial index this projection belongs to */
  uint8_t  ncoast;
  MgPt     v[MG_NV];       /* projected TIN vertices */
  MgSeg    coast[MG_MAX_SEGS];
} MgProjected;

/* Build the coastline from the TIN. Idempotent. */
void mg_init(void);

/* Number of coastline segments found at init (for tests). */
int mg_coast_segments(void);

/* Projection for a dial index, using a Q15 rotation from grid_rotation(). Recomputes
 * only when `key` differs from the cached projection. Returns a pointer to the cache. */
const MgProjected *mg_project(uint16_t key, int32_t sin_q15, int32_t cos_q15);

/* Number of times mg_project actually recomputed (for tests and the debug overlay). */
uint32_t mg_projection_count(void);

/* Static geometry accessors (indices into MgProjected.v). */
void mg_triangle(int i, uint8_t *a, uint8_t *b, uint8_t *c);
bool mg_triangle_filled(int i);
void mg_edge_ends(int i, uint8_t *a, uint8_t *b);
uint8_t mg_ridge_vertex(int i);
